import {RanchRenderer} from './ranch-renderer.js';
import * as T from 'three';

import {OrbitControls} from '/vendor/OrbitControls.js';

import {initTheme,getTheme,setTheme,usePreset,resetTheme,resolveColor,applyToThree,composePalette,isBloomEligible} from './theme-engine.js';

const $=id=>document.getElementById(id),status=$('theme-status'),host=$('theme-viewport');

let group,parts=[],selected='',ticket=0,contract,renderer,camera,controls,scene;

const label=s=>s.charAt(0).toUpperCase()+s.slice(1);

function render(){renderer?.render(scene,camera)}

function fit(){if(!group)return;const b=new T.Box3().setFromObject(group),c=b.getCenter(new T.Vector3()),r=b.getSize(new T.Vector3()).length()/2;const angle=Math.min(camera.fov*Math.PI/360,Math.atan(Math.tan(camera.fov*Math.PI/360)*camera.aspect));camera.position.copy(c).add(new T.Vector3(1,.6,1.4).normalize().multiplyScalar(r/Math.sin(angle)*1.35));controls.target.copy(c);controls.update();render()}

function sync(){const theme=getTheme();$('theme-preset').value=theme.preset;$('theme-identity').checked=theme.recolorIdentity;$('theme-season').value=theme.season;$('theme-weathering').value=theme.weathering*100;$('theme-bloom').value=theme.bloom*100;$('weathering-value').textContent=Math.round(theme.weathering*100)+'%';$('bloom-value').textContent=Math.round(theme.bloom*100)+'%';$('season-note').textContent=theme.season==='winter'?'Cool winter colors. No snow or leaf loss.':theme.season==='original'?'Authored colors, with your chosen finish.':label(theme.season)+' colors, composed across the ranch.';const eligible=parts.some(isBloomEligible);$('bloom-note').textContent=eligible?'Three dimensional flowers grow across this canopy.':'This asset has no eligible flowering canopy. Preview Tree · Standing to see blossoms.';for(const [role,info] of Object.entries(contract.roles)){const color=composePalette(theme)[role]||info.defaultColor;for(const input of document.querySelectorAll(`[data-role="${role}"]`)){input.value=color;input.disabled=info.identity&&!theme.recolorIdentity;}}if(group)applyToThree(group,T);render();window.RanchView?.changed()}

function saved(result){status.textContent=result.saved?'Theme saved on this device.':'Theme applied. Device storage is unavailable.'}

async function show(record){const id=++ticket;status.textContent='Loading preview…';try{const r=await fetch(record.json);if(!r.ok)throw Error('Preview asset is unavailable');const data=await r.json();if(id!==ticket)return;const next=new T.Group();for(const part of data){const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(part.positions,3));if(part.normals?.length===part.positions.length)geometry.setAttribute('normal',new T.Float32BufferAttribute(part.normals,3));else geometry.computeVertexNormals();const mesh=new T.Mesh(geometry,new T.MeshStandardMaterial({color:new T.Color().setRGB(...resolveColor(part),T.SRGBColorSpace),roughness:.9}));mesh.userData.themeSurface=part;next.add(mesh)}if(group){scene.remove(group);group.traverse(m=>{m.geometry?.dispose();m.material?.dispose()})}group=next;parts=data;selected=record.id;scene.add(group);$('preview-caption').textContent=record.label+' · Drag to turn';$('theme-coverage').textContent=`${data.filter(p=>p.role&&p.role!=='unmapped').length} of ${data.length} surfaces have semantic roles. Other surfaces keep their original colors.`;sync();status.textContent='Preview ready.';fit();window.RanchView?.changed()}catch(e){status.textContent=e.message}}

async function start(){contract=await initTheme();const custom=new Option('Your direction','custom');$('theme-preset').append(...contract.presets.map(p=>new Option(p.label,p.id)),custom);$('theme-preset').onchange=e=>{if(e.target.value!=='custom')saved(usePreset(e.target.value))};for(const [role,info] of Object.entries(contract.roles)){const row=document.createElement('div');row.className='palette-row';const name=document.createElement('label');name.htmlFor='color-'+role;name.textContent=label(role);const picker=document.createElement('input');picker.type='color';picker.id=name.htmlFor;picker.dataset.role=role;picker.setAttribute('aria-label',label(role)+' color');const text=document.createElement('input');text.type='text';text.maxLength=7;text.dataset.role=role;text.setAttribute('aria-label',label(role)+' hexadecimal color');text.pattern='#[0-9a-fA-F]{6}';function update(e){if(!/^#[0-9a-f]{6}$/i.test(e.target.value)){e.target.setCustomValidity('Use a six digit hex color, such as #7d9c65.');e.target.reportValidity();return}e.target.setCustomValidity('');const s=getTheme();saved(setTheme({...s,preset:'custom',palette:{...s.palette,[role]:e.target.value}}))}picker.oninput=update;text.onchange=update;row.append(name,picker,text);$('theme-colors').append(row)}$('theme-identity').onchange=e=>saved(setTheme({...getTheme(),recolorIdentity:e.target.checked}));$('theme-reset').onclick=()=>saved(resetTheme());$('theme-season').onchange=e=>saved(setTheme({...getTheme(),preset:'custom',season:e.target.value,palette:{}}));for(const id of ['weathering','bloom'])$('theme-'+id).oninput=e=>saved(setTheme({...getTheme(),preset:'custom',[id]:Number(e.target.value)/100}));window.addEventListener('ranch-theme-change',sync);sync();

scene=new T.Scene();scene.background=new T.Color('#e5e9db');renderer=new RanchRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));host.append(renderer.domElement);camera=new T.PerspectiveCamera(35,1,.01,1000);controls=new OrbitControls(camera,renderer.domElement);controls.enablePan=false;controls.addEventListener('change',()=>{render();window.RanchView?.changed()});scene.add(new T.HemisphereLight('#fff7e8','#8a9e7a',2));const sun=new T.DirectionalLight('#fff1d5',2.5);sun.position.set(-7,12,9);scene.add(sun);new ResizeObserver(()=>{renderer.setSize(host.clientWidth,host.clientHeight,false);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();fit()}).observe(host);$('theme-fit').onclick=fit;

const r=await fetch('/simulation-assets/catalog.json');if(!r.ok)throw Error('Asset catalog unavailable');const records=await r.json();$('theme-asset').append(...records.map(a=>new Option(a.label||a.id,a.id)));$('theme-asset').onchange=e=>show(records.find(a=>a.id===e.target.value));const first=records.find(a=>a.id==='tree-standing')||records[0];$('theme-asset').value=first.id;await show(first);window.RanchView?.register('themes',()=>({theme:getTheme(),asset:selected,surfaces:parts.length,camera:camera?.position.toArray()}),render)}

start().catch(e=>{status.textContent=e.message;console.error(e)});

